-- Salesforce data dump generated from source CSV files
BEGIN;

CREATE TABLE IF NOT EXISTS owners (
  id varchar(36),
  name text,
  role text,
  alias text,
  license text,
  email text,
  email_status boolean,
  profile text,
  username text,
  company text,
  time_zone timestamp,
  division text,
  locale text,
  manager text,
  mobile varchar(15),
  last_login timestamp,
  created_by text,
  cost_center numeric,
  ownership_type text,
  me_sales_goal_usd numeric,
  is_frozen boolean,
  created_at timestamp,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS permissions (
  id varchar(36),
  name text,
  PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS accounts (
  id varchar(36),
  name varchar(100),
  is_deleted boolean,
  billing_address text,
  shipping_address text,
  phone varchar(15),
  fax text,
  owner_id varchar(36),
  created_at timestamp,
  last_activity date,
  national_svp char(36),
  hotel_sol_business_owner char(36),
  advito_business_owner char(36),
  me_business_owner char(36),
  bcd_business_owner char(36),
  latam_ram char(36),
  emea_ram char(36),
  apac_ram char(36),
  na_ram char(36),
  global_account_manager char(36),
  global_executive_sponsor char(36),
  advito_client_status text,
  me_client_status text,
  bcd_client_status text,
  opportunity_count integer,
  industry text,
  PRIMARY KEY (id),
  FOREIGN KEY (owner_id) REFERENCES owners(id),
  FOREIGN KEY (national_svp) REFERENCES owners(id),
  FOREIGN KEY (hotel_sol_business_owner) REFERENCES owners(id),
  FOREIGN KEY (advito_business_owner) REFERENCES owners(id),
  FOREIGN KEY (me_business_owner) REFERENCES owners(id),
  FOREIGN KEY (bcd_business_owner) REFERENCES owners(id),
  FOREIGN KEY (latam_ram) REFERENCES owners(id),
  FOREIGN KEY (emea_ram) REFERENCES owners(id),
  FOREIGN KEY (apac_ram) REFERENCES owners(id),
  FOREIGN KEY (na_ram) REFERENCES owners(id),
  FOREIGN KEY (global_account_manager) REFERENCES owners(id),
  FOREIGN KEY (global_executive_sponsor) REFERENCES owners(id)
);

CREATE TABLE IF NOT EXISTS gcn (
  id varchar(36),
  account_id varchar(36),
  status text,
  client_name text,
  case_number text,
  is_me_gcn boolean,
  client_exp_years integer,
  PRIMARY KEY (id),
  FOREIGN KEY (account_id) REFERENCES accounts(id)
);

CREATE TABLE IF NOT EXISTS agreements (
  id varchar(36),
  name varchar(100),
  account_id varchar(36),
  gcn_id varchar(36),
  contract_type text,
  region text,
  status text,
  effective_date date,
  agreement_end_date date,
  agreement_vp varchar(36),
  owner_id varchar(36),
  renewal_terms text,
  PRIMARY KEY (id),
  FOREIGN KEY (account_id) REFERENCES accounts(id),
  FOREIGN KEY (gcn_id) REFERENCES gcn(id),
  FOREIGN KEY (agreement_vp) REFERENCES owners(id),
  FOREIGN KEY (owner_id) REFERENCES owners(id)
);

CREATE TABLE IF NOT EXISTS countries (
  id varchar(36),
  agreement_id varchar(36),
  name text,
  region text,
  country_status text,
  booking_country text,
  ticket_country text,
  PRIMARY KEY (id),
  FOREIGN KEY (agreement_id) REFERENCES agreements(id)
);

CREATE TABLE IF NOT EXISTS tool_service (
  id char(36),
  product_delivery text,
  product_marketer char(36),
  product_category text,
  name text,
  tool_status text,
  availability_loc text,
  product_type text,
  description text,
  PRIMARY KEY (id),
  FOREIGN KEY (product_marketer) REFERENCES owners(id)
);

CREATE TABLE IF NOT EXISTS annual_vol (
  id char(36),
  name text,
  country_id char(36),
  agreement_id char(36),
  air_transaction integer,
  air_vol numeric,
  train_transaction integer,
  train_vol numeric,
  car_transaction integer,
  car_vol numeric,
  hotel_transaction integer,
  hotel_vol numeric,
  currency_iso_code char(5),
  PRIMARY KEY (id),
  FOREIGN KEY (country_id) REFERENCES countries(id),
  FOREIGN KEY (agreement_id) REFERENCES agreements(id)
);

CREATE TABLE IF NOT EXISTS program_sol (
  id char(36),
  name text,
  country_id char(36),
  product_type text,
  status text,
  trial_exp_date date,
  tool_service_id char(36),
  agreement_id char(36),
  PRIMARY KEY (id),
  FOREIGN KEY (country_id) REFERENCES countries(id),
  FOREIGN KEY (tool_service_id) REFERENCES tool_service(id),
  FOREIGN KEY (agreement_id) REFERENCES agreements(id)
);

CREATE TABLE IF NOT EXISTS owner_permissions (
  owner_id varchar(36),
  permission_id varchar(36),
  PRIMARY KEY (owner_id, permission_id),
  FOREIGN KEY (owner_id) REFERENCES owners(id),
  FOREIGN KEY (permission_id) REFERENCES permissions(id)
);








